INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2055572732997648386, '分析不同年龄段不同性别购买商品差异', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '柱状图', '{\"title\":{\"text\":\"不同年龄段不同性别购买商品数量对比\"},\"tooltip\":{},\"legend\":{\"data\":[\"男\",\"女\"]},\"xAxis\":{\"type\":\"category\",\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45以上\"]},\"yAxis\":{\"type\":\"value\"},\"series\":[{\"name\":\"男\",\"type\":\"bar\",\"data\":[4,9,1,2]},{\"name\":\"女\",\"type\":\"bar\",\"data\":[9,4,2,0]}]}', '从数据可以看出，不同年龄段和性别的购买数量存在明显差异。18-25岁女性购买数量最高（9件），26-35岁男性次之（9件）；45岁以上女性无购买记录，36-45岁男性购买数量最低（1件）。整体呈现年轻群体购买活跃度更高的特点，且同一年龄段内性别间购买行为差异显著。', '1', '成功', 2043241068644618241, '2026-05-16 16:55:04', '2026-05-16 16:55:04', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2055574377735241729, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\"title\":{\"text\":\"不同年龄段对不同商品的销售金额\"},\"tooltip\":{\"trigger\":\"axis\"},\"legend\":{\"data\":[\"18-25岁\",\"26-35岁\",\"36-45岁\",\"45岁以上\"]},\"xAxis\":{\"type\":\"category\",\"data\":[\"电子产品\",\"美妆护肤\",\"家居日用\",\"服装鞋帽\",\"零食饮料\"]},\"yAxis\":{\"type\":\"value\",\"name\":\"销售金额\"},\"series\":[{\"name\":\"18-25岁\",\"type\":\"line\",\"data\":[399,268,125,329,89]},{\"name\":\"26-35岁\",\"type\":\"line\",\"data\":[799,199,159,569,68]},{\"name\":\"36-45岁\",\"type\":\"line\",\"data\":[1898,0,0,459,0]},{\"name\":\"45岁以上\",\"type\":\"line\",\"data\":[0,0,239,0,0]}]}', '从数据可以看出，不同年龄段消费者对不同商品的偏好存在明显差异。18-25岁群体在服装鞋帽和电子产品上的消费较高；26-35岁群体在服装鞋帽和电子产品消费突出，同时家居日用也有一定消费；36-45岁群体主要消费集中在电子产品和服装鞋帽，其中电子产品消费远超其他年龄段；45岁以上群体仅在家居日用上有消费记录。整体而言，电子产品在各年龄段均有较高消费，尤其是36-45岁群体；服装鞋帽在年轻和中年群体中较受欢迎；美妆护肤和零食饮料消费主要集中在18-25岁和26-35岁群体。', '1', '成功', 2043241068644618241, '2026-05-16 17:01:37', '2026-05-16 17:02:28', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2057276319389724673, '按下单日期统计每日的订单量、销售额、购买数量，分析销售的日度波动规律，识别销售高峰与低谷', '每日销售趋势分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"每日销售数据趋势\",\n    \"left\": \"center\"\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": function(params) {\n      return params[0].name + \'<br/>\' +\n             \'订单量: \' + params[1].value + \' 笔<br/>\' +\n             \'销售额: ¥\' + params[2].value + \'<br/>\' +\n             \'购买数量: \' + params[3].value + \' 件\';\n    }\n  },\n  \"legend\": {\n    \"data\": [\"订单量\", \"销售额\", \"购买数量\"],\n    \"top\": \"5%\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"toolbox\": {\n    \"feature\": {\n      \"saveAsImage\": {}\n    }\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"boundaryGap\": false,\n    \"data\": [\"2025/1/5\", \"2025/1/6\", \"2025/1/7\", \"2025/1/8\", \"2025/1/9\", \"2025/1/10\", \"2025/1/11\", \"2025/1/12\"]\n  },\n  \"yAxis\": [\n    {\n      \"type\": \"value\",\n      \"name\": \"数量\",\n      \"min\": 0,\n      \"max\": 10,\n      \"interval\": 2\n    },\n    {\n      \"type\": \"value\",\n      \"name\": \"金额\",\n      \"min\": 0,\n      \"max\": 1700,\n      \"interval\": 200\n    }\n  ],\n  \"series\": [\n    {\n      \"name\": \"订单量\",\n      \"type\": \"line\",\n      \"stack\": \"总量\",\n      \"areaStyle\": {},\n      \"emphasis\": {\n        \"focus\": \"series\"\n      },\n      \"yAxisIndex\": 0,\n      \"data\": [2, 2, 2, 2, 2, 2, 2, 1]\n    },\n    {\n      \"name\": \"销售额\",\n      \"type\": \"line\",\n      \"stack\": \"总量\",\n      \"areaStyle\": {},\n      \"emphasis\": {\n        \"focus\": \"series\"\n      },\n      \"yAxisIndex\": 1,\n      \"data\": [667, 618, 888, 438, 1628, 637, 724, 156]\n    },\n    {\n      \"name\": \"购买数量\",\n      \"type\": \"line\",\n      \"stack\": \"总量\",\n      \"areaStyle\": {},\n      \"emphasis\": {\n        \"focus\": \"series\"\n      },\n      \"yAxisIndex\": 0,\n      \"data\": [3, 4, 7, 3, 3, 7, 3, 1]\n    }\n  ]\n}', '根据对数据的分析，我发现以下规律：\n1. 销售高峰出现在1月9日，当日销售额达1628元，主要是由于有一笔大额电子产品订单(1299元)\n2. 销售低谷在1月12日，仅有一笔订单，销售额为156元\n3. 订单量整体较为稳定，除最后一天外均为2笔订单\n4. 购买数量呈现一定波动，1月7日和1月10日购买数量较多(分别为7件)，而1月12日最少(1件)\n5. 销售额波动较大，受高价值商品订单影响明显', '1', '成功', 2043241068644618241, '2026-05-21 09:44:31', '2026-05-21 10:33:33', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2057279841841713153, '按下单日期统计每日的订单量、销售额、购买数量，分析销售的日度波动规律，识别销售高峰与低谷', '每日销售趋势分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\"title\":{\"text\":\"每日销售数据趋势\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"axis\",\"axisPointer\":{\"type\":\"cross\",\"label\":{\"backgroundColor\":\"#6a7985\"}}},\"legend\":{\"data\":[\"订单量\",\"销售额\",\"购买数量\"],\"top\":30},\"grid\":{\"left\":\"3%\",\"right\":\"4%\",\"bottom\":\"3%\",\"containLabel\":true,\"top\":\"15%\"},\"xAxis\":{\"type\":\"category\",\"boundaryGap\":false,\"data\":[\"2025/1/5\",\"2025/1/6\",\"2025/1/7\",\"2025/1/8\",\"2025/1/9\",\"2025/1/10\",\"2025/1/11\",\"2025/1/12\"]},\"yAxis\":[{\"type\":\"value\",\"name\":\"订单量/购买数量\",\"min\":0,\"max\":8,\"interval\":1},{\"type\":\"value\",\"name\":\"销售额\",\"min\":0,\"max\":1700,\"interval\":200}]},\n\"series\":[{\n    \"name\":\"订单量\",\n    \"type\":\"line\",\n    \"stack\":\"总量\",\n    \"areaStyle\":{},\n    \"emphasis\":{\"focus\":\"series\"},\n    \"data\":[2,2,2,2,2,2,2,1],\n    \"yAxisIndex\":0,\n    \"color\":\"#5470c6\"\n},{\n    \"name\":\"购买数量\",\n    \"type\":\"line\",\n    \"stack\":\"总量\",\n    \"areaStyle\":{},\n    \"emphasis\":{\"focus\":\"series\"},\n    \"data\":[3,4,7,3,3,7,3,1],\n    \"yAxisIndex\":0,\n    \"color\":\"#91cc75\"\n},{\n    \"name\":\"销售额\",\n    \"type\":\"line\",\n    \"stack\":\"总量\",\n    \"areaStyle\":{},\n    \"emphasis\":{\"focus\":\"series\"},\n    \"data\":[667,618,888,438,1628,637,724,156],\n    \"yAxisIndex\":1,\n    \"color\":\"#ee6666\"\n}]}', '根据对数据的统计分析，发现以下几点规律：1月9日销售额达到峰值1628元，1月8日销售额最低仅438元；购买数量在1月7日和10日均达到7件的最高值；订单量整体保持稳定，仅1月12日降至1单。销售数据呈现出明显的日度波动特征，需进一步分析高峰与低谷的形成原因。', '1', '成功', 2043241068644618241, '2026-05-21 09:58:31', '2026-05-21 10:33:31', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2057281147348193281, '不同性别的订单量、消费金额、购买数量占比', '销售趋势分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '柱状图', '{\"title\":{\"text\":\"不同性别的订单量、消费金额、购买数量占比\"},\"tooltip\":{\"trigger\":\"axis\",\"formatter\":\"{b}: {c}%\"},\"legend\":{\"data\":[\"订单量占比\",\"消费金额占比\",\"购买数量占比\"]},\"xAxis\":{\"type\":\"category\",\"data\":[\"男\",\"女\"]},\"yAxis\":{\"type\":\"value\",\"axisLabel\":{\"formatter\":\"{value}%\"}},\"series\":[{\"name\":\"订单量占比\",\"type\":\"bar\",\"data\":[53.33,46.67],\"label\":{\"show\":true,\"position\":\"top\",\"formatter\":\"{c}%\"}},{\"name\":\"消费金额占比\",\"type\":\"bar\",\"data\":[47.74,52.26],\"label\":{\"show\":true,\"position\":\"top\",\"formatter\":\"{c}%\"}},{\"name\":\"购买数量占比\",\"type\":\"bar\",\"data\":[51.61,48.39],\"label\":{\"show\":true,\"position\":\"top\",\"formatter\":\"{c}%\"}}]}', '从数据统计结果来看，男性订单量为8单（占53.33%）、消费金额2748元（占47.74%）、购买数量16件（占51.61%）；女性订单量为7单（占46.67%）、消费金额3008元（占52.26%）、购买数量15件（占48.39%）。整体呈现男性在订单量和购买数量上略高于女性，而女性在消费金额上略高的特点。', '1', '成功', 2043241068644618241, '2026-05-21 10:03:42', '2026-05-21 10:03:42', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2057385663020154882, '分析不同年龄段对不同商品的销售金额占比', '销售趋势分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '饼图', '{\"title\":{\"text\":\"不同年龄段商品销售金额占比\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"item\",\"formatter\":\"{a} <br/>{b}: {c} ({d}%)\"},\"series\":[{\"name\":\"18-25岁\",\"type\":\"pie\",\"radius\":\"30%\",\"center\":[\"25%\",\"25%\"],\"data\":[{\"name\":\"电子产品\",\"value\":399},{\"name\":\"美妆护肤\",\"value\":424},{\"name\":\"零食饮料\",\"value\":89},{\"name\":\"服装鞋帽\",\"value\":329},{\"name\":\"家居日用\",\"value\":125}]},{\"name\":\"26-35岁\",\"type\":\"pie\",\"radius\":\"30%\",\"center\":[\"75%\",\"25%\"],\"data\":[{\"name\":\"家居日用\",\"value\":159},{\"name\":\"电子产品\",\"value\":799},{\"name\":\"美妆护肤\",\"value\":199},{\"name\":\"零食饮料\",\"value\":68},{\"name\":\"服装鞋帽\",\"value\":569}]},{\"name\":\"36-45岁\",\"type\":\"pie\",\"radius\":\"30%\",\"center\":[\"25%\",\"75%\"],\"data\":[{\"name\":\"服装鞋帽\",\"value\":459},{\"name\":\"电子产品\",\"value\":1898}]},{\"name\":\"45岁以上\",\"type\":\"pie\",\"radius\":\"30%\",\"center\":[\"75%\",\"75%\"],\"data\":[{\"name\":\"家居日用\",\"value\":239}]}]}', '从数据来看，不同年龄段对商品的偏好差异明显：  \n1. 18-25岁群体：美妆护肤（31%）和电子产品（29%）是最主要的消费品类，其次是服装鞋帽（24%），零食饮料和家居日用占比较小。  \n2. 26-35岁群体：电子产品（44.5%）占比最高，服装鞋帽（31.7%）次之，美妆护肤和家居日用也有一定份额，零食饮料占比最低。  \n3. 36-45岁群体：电子产品占据绝对主导地位（80.5%），服装鞋帽仅占19.5%。  \n4. 45岁以上群体：仅有家居日用一项消费，占比100%。  \n\n这表明随着年龄增长，电子产品成为核心消费品类，尤其是36-45岁群体；而年轻群体（18-25）则更倾向于美妆护肤和电子产品；45岁以上群体的消费品类较为单一。', '1', '成功', 2043241068644618241, '2026-05-21 16:59:01', '2026-05-21 16:59:01', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2057390409231745025, '分析不同年龄段销售金额占比', '销售趋势分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '堆叠图', '{\"title\":{\"text\":\"不同年龄段销售金额占比\"},\"tooltip\":{\"trigger\":\"axis\",\"axisPointer\":{\"type\":\"shadow\"}},\"legend\":{\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45以上\"]},\"grid\":{\"left\":\"3%\",\"right\":\"4%\",\"bottom\":\"3%\",\"containLabel\":true},\"xAxis\":{\"type\":\"value\",\"boundaryGap\":[0,0.01]},\"yAxis\":{\"type\":\"category\",\"data\":[\"销售金额\"]},\"series\":[{\"name\":\"18-25\",\"type\":\"bar\",\"stack\":\"总量\",\"data\":[1366]},{\"name\":\"26-35\",\"type\":\"bar\",\"stack\":\"总量\",\"data\":[1794]},{\"name\":\"36-45\",\"type\":\"bar\",\"stack\":\"总量\",\"data\":[2357]},{\"name\":\"45以上\",\"type\":\"bar\",\"stack\":\"总量\",\"data\":[239]}]}', '通过分析不同年龄段的销售金额数据，发现各年龄段消费能力存在显著差异。36-45岁年龄段销售金额占比最高（约41%），其次是26-35岁（约31%），18-25岁（约24%）紧随其后，45岁以上年龄段占比最低（约4%）。这表明中年消费者是核心消费群体，年轻群体也具备一定消费潜力，而老年群体的消费能力相对较弱。', '1', '成功', 2043241068644618241, '2026-05-21 17:17:52', '2026-05-21 17:17:52', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2058208647070949377, '分析不同年龄段销售金额占比\n\n', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '仪表盘', '{\"title\":{\"text\":\"不同年龄段销售金额占比\"},\"series\":[{\"type\":\"gauge\",\"data\":[{\"value\":23.73,\"name\":\"18-25岁\"},{\"value\":31.17,\"name\":\"26-35岁\"},{\"value\":40.95,\"name\":\"36-45岁\"},{\"value\":4.15,\"name\":\"45岁以上\"}]}]}', '从数据来看，36-45岁年龄段销售金额占比最高，达到约40.95%；其次是26-35岁年龄段，占比约31.17%；18-25岁年龄段占比约23.73%；45岁以上年龄段占比最低，仅约4.15%。这表明中年群体（36-45岁）是主要的消费群体，而老年群体（45岁以上）的消费占比较小。', '1', '成功', 2043241068644618241, '2026-05-23 23:29:15', '2026-05-24 16:12:52', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2058774552175796225, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '柱状图', '{\"title\":{\"text\":\"不同年龄段对不同商品的销售金额\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"axis\",\"axisPointer\":{\"type\":\"shadow\"}},\"legend\":{\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45 以上\"]},\"grid\":{\"left\":\"3%\",\"right\":\"4%\",\"bottom\":\"3%\",\"containLabel\":true},\"xAxis\":{\"type\":\"category\",\"data\":[\"电子产品\",\"美妆护肤\",\"家居日用\",\"服装鞋帽\",\"零食饮料\"]},\"yAxis\":{\"type\":\"value\",\"name\":\"销售金额\"},\"series\":[{\"name\":\"18-25\",\"type\":\"bar\",\"data\":[399,268,125,329,89]},{\"name\":\"26-35\",\"type\":\"bar\",\"data\":[799,199,159,569,68]},{\"name\":\"36-45\",\"type\":\"bar\",\"data\":[1898,0,0,459,0]},{\"name\":\"45 以上\",\"type\":\"bar\",\"data\":[0,0,239,0,0]}]}', '分析显示，不同年龄段对商品的偏好差异明显。36-45岁年龄段在电子产品上的消费金额最高，达到1898元。26-35岁年龄段在服装鞋帽上的消费领先，为569元。18-25岁年龄段在电子产品上的消费最高，为399元。电子产品是所有年龄段中总销售额最高的商品类别。45岁以上年龄段的购买量最少，且仅购买家居日用商品。', '1', '成功', 2043241068644618241, '2026-05-25 12:57:58', '2026-05-27 15:54:32', 1);
