INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2058801481570426882, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\"title\":{\"text\":\"不同年龄段对不同商品的销售金额\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"axis\"},\"legend\":{\"data\":[\"电子产品\",\"美妆护肤\",\"家居日用\",\"服装鞋帽\",\"零食饮料\"],\"top\":\"10%\"},\"grid\":{\"left\":\"3%\",\"right\":\"4%\",\"bottom\":\"3%\",\"containLabel\":true},\"xAxis\":{\"type\":\"category\",\"boundaryGap\":false,\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45以上\"]},\"yAxis\":{\"type\":\"value\",\"name\":\"销售金额（元）\"},\"series\":[{\"name\":\"电子产品\",\"type\":\"line\",\"data\":[399,799,1299,0]},{\"name\":\"美妆护肤\",\"type\":\"line\",\"data\":[268,199,0,0]},{\"name\":\"家居日用\",\"type\":\"line\",\"data\":[125,159,0,239]},{\"name\":\"服装鞋帽\",\"type\":\"line\",\"data\":[329,569,459,0]},{\"name\":\"零食饮料\",\"type\":\"line\",\"data\":[89,68,0,0]}]}', '不同年龄段对商品的销售金额存在明显差异，36-45岁年龄段在电子产品上的销售金额最高（1299元），18-25岁在美妆护肤（268元）和服装鞋帽（329元）有较高消费，26-35岁在家居日用（159元）和服装鞋帽（569元）上支出较多，45岁以上仅在家居日用有消费（239元）。各年龄段在不同商品类别的消费偏好不同，整体呈现年龄段与商品类别的关联性。', '1', '成功', 2043241068644618241, '2026-05-25 14:44:58', '2026-05-25 14:53:56', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2058802239162392578, '分析不同年龄段对不同商品的销售金额\n', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\"title\":{\"text\":\"不同年龄段对不同商品的销售金额\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"axis\"},\"legend\":{\"data\":[\"电子产品\",\"美妆护肤\",\"家居日用\",\"服装鞋帽\",\"零食饮料\"],\"bottom\":\"10\"},\"xAxis\":{\"type\":\"category\",\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45以上\"]},\"yAxis\":{\"type\":\"value\",\"name\":\"销售金额\"},\"series\":[{\"name\":\"电子产品\",\"type\":\"line\",\"data\":[399,799,1898,0],\"smooth\":true},{\"name\":\"美妆护肤\",\"type\":\"line\",\"data\":[268,199,0,0],\"smooth\":true},{\"name\":\"家居日用\",\"type\":\"line\",\"data\":[125,159,0,239],\"smooth\":true},{\"name\":\"服装鞋帽\",\"type\":\"line\",\"data\":[329,569,459,0],\"smooth\":true},{\"name\":\"零食饮料\",\"type\":\"line\",\"data\":[89,68,0,0],\"smooth\":true}]}', '分析不同年龄段对不同商品的销售金额发现，18-25岁群体在电子产品、美妆护肤、服装鞋帽和零食饮料上有销售，其中电子产品和服装鞋帽金额较高；26-35岁群体在电子产品、服装鞋帽、家居日用和美妆护肤上有销售，电子产品和服装鞋帽金额突出；36-45岁群体主要在电子产品（尤其是高价值产品）上有较高销售；45岁以上群体仅在家居日用有销售。整体来看，电子产品在36-45岁年龄段销售金额最高，其次是26-35岁；美妆护肤和零食饮料集中在年轻群体；服装鞋帽在26-35岁年龄段销售金额最高。', '1', '成功', 2043241068644618241, '2026-05-25 14:47:59', '2026-05-25 14:48:46', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2059525272160182273, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '柱状图', '{\"title\":{\"text\":\"不同年龄段对不同商品的销售金额\",\"left\":\"center\"},\"tooltip\":{\"trigger\":\"axis\",\"axisPointer\":{\"type\":\"shadow\"}},\"legend\":{\"data\":[\"18-25\",\"26-35\",\"36-45\",\"45以上\"],\"top\":30},\"grid\":{\"left\":\"3%\",\"right\":\"4%\",\"bottom\":\"3%\",\"containLabel\":true},\"xAxis\":{\"type\":\"category\",\"data\":[\"电子产品\",\"美妆护肤\",\"家居日用\",\"服装鞋帽\",\"零食饮料\"]},\"yAxis\":{\"type\":\"value\",\"name\":\"销售金额\",\"axisLabel\":{\"formatter\":\"{value} 元\"}},\"series\":[{\"name\":\"18-25\",\"type\":\"bar\",\"data\":[399,424,125,329,89]},{\"name\":\"26-35\",\"type\":\"bar\",\"data\":[799,199,159,569,68]},{\"name\":\"36-45\",\"type\":\"bar\",\"data\":[1898,0,0,459,0]},{\"name\":\"45以上\",\"type\":\"bar\",\"data\":[0,0,239,0,0]}]}', '不同年龄段对商品的销售金额存在明显差异。18-25岁年龄段在美妆护肤（424元）和服装鞋帽（329元）上销售金额较高；26-35岁年龄段在电子产品（799元）和服装鞋帽（569元）上表现突出；36-45岁年龄段在电子产品（1898元）和服装鞋帽（459元）上销售金额最高，尤其是电子产品；45岁以上年龄段仅在家居日用（239元）有销售记录。整体来看，电子产品和服装鞋帽是各年龄段较为关注的商品类别，零食饮料销售金额相对较低。', '1', '成功', 2043241068644618241, '2026-05-27 14:41:03', '2026-05-27 14:41:46', 0);
