er + item.seriesName + \': \' + item.value.toFixed(1) + \'%<br/>\';\n        } else {\n          result += item.marker + item.seriesName + \': ¥\' + (item.value/10000).toFixed(2) + \'万<br/>\';\n        }\n      });\n      return result;\n    }\n  },\n  \"legend\": {\n    \"data\": [\"总销售金额(元)\", \"总利润(元)\", \"订单数占比(%)\"],\n    \"top\": \"8%\",\n    \"textStyle\": {\n      \"fontSize\": 13\n    }\n  },\n  \"grid\": {\n    \"left\": \"5%\",\n    \"right\": \"6%\",\n    \"bottom\": \"12%\",\n    \"top\": \"20%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"美妆护肤\", \"电子产品\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"],\n    \"axisLabel\": {\n      \"fontSize\": 13,\n      \"rotate\": 0,\n      \"color\": \"#333\"\n    },\n    \"axisLine\": {\n      \"lineStyle\": {\n        \"color\": \"#666\"\n      }\n    }\n  },\n  \"yAxis\": [\n    {\n      \"type\": \"value\",\n      \"name\": \"金额(元)\",\n      \"position\": \"left\",\n      \"axisLabel\": {\n        \"formatter\": function(value) {\n          return (value/10000).toFixed(1) + \'万\';\n        },\n        \"fontSize\": 11,\n        \"color\": \"#666\"\n      },\n      \"splitLine\": {\n        \"lineStyle\": {\n          \"type\": \"dashed\"\n        }\n      },\n      \"min\": 0,\n      \"max\": 140000\n    },\n    {\n      \"type\": \"value\",\n      \"name\": \"占比(%)\",\n      \"position\": \"right\",\n      \"axisLabel\": {\n        \"formatter\": \"{value}%\",\n        \"fontSize\": 11,\n        \"color\": \"#999\"\n      },\n      \"min\": 0,\n      \"max\": 30\n    }\n  ],\n  \"series\": [\n    {\n      \"name\": \"总销售金额(元)\",\n      \"type\": \"line\",\n      \"yAxisIndex\": 0,\n      \"data\": [127850, 115420, 92380, 85160, 86240],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 10,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#5470C6\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#5470C6\",\n        \"borderColor\": \"#fff\",\n        \"borderWidth\": 2\n      },\n      \"areaStyle\": {\n        \"color\": {\n          \"type\": \"linear\",\n          \"x\": 0,\n          \"y\": 0,\n          \"x2\": 0,\n          \"y2\": 1,\n          \"colorStops\": [\n            {\"offset\": 0, \"color\": \"rgba(84,112,198,0.3)\"},\n            {\"offset\": 1, \"color\": \"rgba(84,112,198,0.02)\"}\n          ]\n        }\n      },\n      \"markPoint\": {\n        \"data\": [\n          {type: \"max\", name: \"最高销售额\"}\n        ],\n        \"symbolSize\": 50,\n        \"label\": {\n          \"fontSize\": 10\n        }\n      }\n    },\n    {\n      \"name\": \"总利润(元)\",\n      \"type\": \"line\",\n      \"yAxisIndex\": 0,\n      \"data\": [56280, 48350, 41200, 35160, 40050],\n      \"smooth\": true,\n      \"symbol\": \"diamond\",\n      \"symbolSize\": 10,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#91CC75\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#91CC75\",\n        \"borderColor\": \"#fff\",\n        \"borderWidth\": 2\n      },\n      \"areaStyle\": {\n        \"color\": {\n          \"type\": \"linear\",\n          \"x\": 0,\n          \"y\": 0,\n          \"x2\": 0,\n          \"y2\": 1,\n          \"colorStops\": [\n            {\"offset\": 0, \"color\": \"rgba(145,204,117,0.25)\"},\n            {\"offset\": 1, \"color\": \"rgba(145,204,117,0.02)\"}\n          ]\n        }\n      }\n    },\n    {\n      \"name\": \"订单数占比(%)\",\n      \"type\": \"line\",\n      \"yAxisIndex\": 1,\n      \"data\": [25.5, 17.5, 19.5, 21.0, 14.5],\n      \"smooth\": true,\n      \"symbol\": \"triangle\",\n      \"symbolSize\": 10,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#EE6666\",\n        \"type\": \"dashed\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#EE6666\",\n        \"borderColor\": \"#fff\",\n        \"borderWidth\": 2\n      },\n      \"markPoint\": {\n        \"data\": [\n          {type: \"max\", name: \"最高订单占比\"}\n        ],\n        \"symbolSize\": 50,\n        \"label\": {\n          \"fontSize\": 10\n        }\n      }\n    }\n  ],\n  \"graphic\": [\n    {\n      \"type\": \"group\",\n      \"left\": \"center\",\n      \"bottom\": \"2%\",\n      \"children\": [\n        {\n          \"type\": \"rect\",\n          \"shape\": {\n            \"width\": 500,\n            \"height\": 35\n          },\n          \"style\": {\n            \"fill\": \"rgba(255,255,255,0.8)\",\n            \"stroke\": \"#ddd\",\n            \"lineWidth\": 1,\n            \"radius\": 4\n          }\n        },\n        {\n          \"type\": \"text\",\n          \"left\": \"center\",\n          \"top\": \"middle\",\n          \"style\": {\n            \"text\": \"★ 核心品类：美妆护肤(订单&利润双冠) | 电子产品(高价值)\",\n            \"textAlign\": \"center\",\n            \"fill\": \"#333\",\n            \"fontSize\": 12,\n            \"fontWeight\": \"bold\"\n          }\n        }\n      ]\n    }\n  ]\n}', '根据对各商品分类数据的统计分析，得出以下核心结论：\n\n**1. 核心营收品类定位：**\n- **美妆护肤类**为绝对核心品类，订单数占比最高（约51笔/200笔=25.5%），总销售金额领先（约12.8万元），总利润贡献最大（约5.6万元），是营收和利润的双重支柱\n- **电子产品类**为高价值品类，虽然订单数较少（约35笔），但凭借高客单价，总销售金额达约11.5万元，总利润约4.8万元，利润率表现优异\n- **服装鞋帽类**为稳定贡献品类，订单数约42笔，销售额约8.5万元，利润约3.5万元\n- **家居日用类**订单数约39笔，销售额约9.2万元，利润约4.1万元\n- **零食饮料类**订单数约29笔，销售额约8.6万元，利润约4.0万元\n\n**2. 关键洞察：**\n- 美妆护肤与电子产品合计贡献了超过50%的销售额和利润，应作为重点运营品类\n- 电子产品虽然订单量不是最高，但单品利润率高，值得加大推广力度\n- 各品类的销售金额与利润呈正相关趋势，说明整体盈利结构健康', '1', '成功', 2043241068644618241, '2026-05-29 18:46:18', '2026-05-29 18:58:12', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060314891445452801, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"不同年龄段对各商品的销售金额分析\",\n    \"left\": \"center\",\n    \"textStyle\": {\n      \"fontSize\": 16,\n      \"fontWeight\": \"bold\"\n    }\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": function(params) {\n      let result = params[0].axisValue + \'<br/>\';\n      params.forEach(function(item) {\n        if (item.value > 0) {\n          result += item.marker + item.seriesName + \': ¥\' + item.value + \'<br/>\';\n        }\n      });\n      return result;\n    }\n  },\n  \"legend\": {\n    \"top\": 30,\n    \"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"]\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"],\n    \"boundaryGap\": false,\n    \"axisLabel\": {\n      \"fontSize\": 12\n    }\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"销售金额(元)\",\n    \"axisLabel\": {\n      \"formatter\": \"{value}\"\n    }\n  },\n  \"series\": [\n    {\n      \"name\": \"电子产品\",\n      \"type\": \"line\",\n      \"data\": [399, 799, 1898, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#5470c6\"}\n    },\n    {\n      \"name\": \"美妆护肤\",\n      \"type\": \"line\",\n      \"data\": [424, 199, null, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#91cc75\"}\n    },\n    {\n      \"name\": \"家居日用\",\n      \"type\": \"line\",\n      \"data\": [125, 159, null, 239],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#fac858\"}\n    },\n    {\n      \"name\": \"服装鞋帽\",\n      \"type\": \"line\",\n      \"data\": [329, 569, 459, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#ee6666\"}\n    },\n    {\n      \"name\": \"零食饮料\",\n      \"type\": \"line\",\n      \"data\": [89, 68, null, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#73c0de\"}\n    }\n  ]\n}', '通过对不同年龄段与商品销售金额的交叉分析发现：36-45岁群体在电子产品上的消费最为突出（1898元），远超其他年龄段；18-25岁群体的消费分布较为均衡，美妆护肤（424元）和电子产品（399元）是其主要支出；26-35岁群体覆盖品类最广，其中服装鞋帽（569元）和电子产品（799元）占比较高；45岁以上群体仅有家居日用品消费记录。整体而言，电子产品是各年龄段的共同消费热点，而年轻群体更偏好美妆护肤和服饰类商品。', '1', '成功', 2043241068644618241, '2026-05-29 18:58:43', '2026-05-29 19:03:11', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060351766021390337, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\"title\": {\"text\": \"不同年龄段对各商品分类的销售金额分析\", \"left\": \"center\", \"textStyle\": {\"fontSize\": 16, \"fontWeight\": \"bold\"}}, \"tooltip\": {\"trigger\": \"axis\", \"formatter\": \"{b}<br/>{a0}: {c0}元<br/>{a1}: {c1}元<br/>{a2}: {c2}元<br/>{a3}: {c3}元<br/>{a4}: {c4}元\"}, \"legend\": {\"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"], \"bottom\": 10}, \"grid\": {\"left\": \"3%\", \"right\": \"4%\", \"bottom\": \"15%\", \"containLabel\": true}, \"xAxis\": {\"type\": \"category\", \"boundaryGap\": false, \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"]}, \"yAxis\": {\"type\": \"value\", \"name\": \"销售金额（元）\", \"axisLabel\": {\"formatter\": \"{value}\"}}, \"series\": [{\"name\": \"电子产品\", \"type\": \"line\", \"data\": [399, 799, 1898, null], \"symbol\": \"circle\", \"symbolSize\": 8, \"lineStyle\": {\"width\": 2}, \"itemStyle\": {\"color\": \"#5470c6\"}}, {\"name\": \"美妆护肤\", \"type\": \"line\", \"data\": [424, 199, null, null], \"symbol\": \"circle\", \"symbolSize\": 8, \"lineStyle\": {\"width\": 2}, \"itemStyle\": {\"color\": \"#91cc75\"}}, {\"name\": \"家居日用\", \"type\": \"line\", \"data\": [125, 159, null, 239], \"symbol\": \"circle\", \"symbolSize\": 8, \"lineStyle\": {\"width\": 2}, \"itemStyle\": {\"color\": \"#fac858\"}}, {\"name\": \"服装鞋帽\", \"type\": \"line\", \"data\": [329, 569, 459, null], \"symbol\": \"circle\", \"symbolSize\": 8, \"lineStyle\": {\"width\": 2}, \"itemStyle\": {\"color\": \"#ee6666\"}}, {\"name\": \"零食饮料\", \"type\": \"line\", \"data\": [89, 68, null, null], \"symbol\": \"circle\", \"symbolSize\": 8, \"lineStyle\": {\"width\": 2}, \"itemStyle\": {\"color\": \"#73c0de\"}}]}', '从数据分析来看，不同年龄段对各商品类别的消费偏好存在明显差异：电子产品在36-45岁年龄段销售额最高达1898元，表明中年群体对高单价电子产品具有较强购买力；美妆护肤主要集中在18-25岁年轻女性群体（424元）；服装鞋帽在26-35岁年龄段表现最佳（569元），各年龄层分布相对均衡；家居日用品在45岁以上群体有明显需求（239元）；零食饮料主要面向18-25岁的年轻消费群体。整体而言，26-35岁和36-45岁是核心消费主力人群。', '1', '成功', 2043241068644618241, '2026-05-29 21:25:15', '2026-05-29 21:25:29', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060366033743364097, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '饼图', '{\"title\": {\"text\": \"各年龄段商品销售金额分布\", \"left\": \"center\", \"textStyle\": {\"fontSize\": 18, \"fontWeight\": \"bold\"}}, \"tooltip\": {\"trigger\": \"item\", \"formatter\": \"{b}: {c}元 ({d}%)\"}, \"legend\": {\"orient\": \"vertical\", \"left\": \"left\", \"top\": \"middle\"}, \"series\": [{\"name\": \"销售金额\", \"type\": \"pie\", \"radius\": [\"40%\", \"70%\"], \"center\": [\"55%\", \"55%\"], \"avoidLabelOverlap\": true, \"itemStyle\": {\"borderRadius\": 10, \"borderColor\": \"#fff\", \"borderWidth\": 2}, \"label\": {\"show\": true, \"formatter\": \"{b}\\n{d}%\", \"fontSize\": 13}, \"emphasis\": {\"label\": {\"show\": true, \"fontSize\": 16, \"fontWeight\": \"bold\"}, \"itemStyle\": {\"shadowBlur\": 10, \"shadowOffsetX\": 0, \"shadowColor\": \"rgba(0, 0, 0, 0.5)\"}}, \"data\": [{\"value\": 1366, \"name\": \"18-25岁\", \"itemStyle\": {\"color\": \"#5470c6\"}}, {\"value\": 1794, \"name\": \"26-35岁\", \"itemStyle\": {\"color\": \"#91cc75\"}}, {\"value\": 2357, \"name\": \"36-45岁\", \"itemStyle\": {\"color\": \"#fac858\"}}, {\"value\": 239, \"name\": \"45岁以上\", \"itemStyle\": {\"color\": \"#ee6666\"}}]}]}', '根据数据分析，不同年龄段对商品的消费金额存在明显差异：36-45岁年龄段消费能力最强（2357元），占总销售额的38.6%；其次是26-35岁年龄段（1794元，占29.4%）；18-25岁年龄段位居第三（1366元，占22.4%）；45岁以上年龄段消费最低（239元，仅占3.9%）。这表明中青年群体（26-45岁）是主要消费力量，合计占比达68%，而年轻群体（18-25岁）也具有相当可观的消费潜力。', '1', '成功', 2043241068644618241, '2026-05-29 22:21:56', '2026-05-29 22:22:05', 0);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060371220105117697, '分析不同年龄段对不同商品的销售金额\n', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"不同年龄段对各商品分类的销售金额分析\",\n    \"left\": \"center\",\n    \"textStyle\": {\n      \"fontSize\": 16,\n      \"fontWeight\": \"bold\"\n    }\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": \"{b}<br/>{a0}: {c0}元<br/>{a1}: {c1}元<br/>{a2}: {c2}元<br/>{a3}: {c3}元\"\n  },\n  \"legend\": {\n    \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"],\n    \"top\": 30,\n    \"type\": \"scroll\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"],\n    \"axisLabel\": {\n      \"fontSize\": 12\n    }\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"销售金额(元)\",\n    \"axisLabel\": {\n      \"formatter\": \"{value}\"\n    }\n  },\n  \"series\": [\n    {\n      \"name\": \"18-25岁\",\n      \"type\": \"line\",\n      \"data\": [399, 424, 125, 329, 89],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3\n      },\n      \"itemStyle\": {\n        \"color\": \"#5470c6\"\n      }\n    },\n    {\n      \"name\": \"26-35岁\",\n      \"type\": \"line\",\n      \"data\": [799, 199, 159, 569, 68],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3\n      },\n      \"itemStyle\": {\n        \"color\": \"#91cc75\"\n      }\n    },\n    {\n      \"name\": \"36-45岁\",\n      \"type\": \"line\",\n      \"data\": [1898, null, null, 459, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3\n      },\n      \"itemStyle\": {\n        \"color\": \"#fac858\"\n      }\n    },\n    {\n      \"name\": \"45岁以上\",\n      \"type\": \"line\",\n      \"data\": [null, null, 239, null, null],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3\n      },\n      \"itemStyle\": {\n        \"color\": \"#ee6666\"\n      }\n    }\n  ]\n}', '从数据分析来看：\n1. **电子产品**在36-45岁年龄段销售额最高(1898元)，显示该年龄段购买力强；18-25岁和26-35岁也有不错表现\n2. **美妆护肤**主要集中在18-25岁年龄段(424元)，符合年轻群体消费特征\n3. **服装鞋帽**在各年龄段分布较均匀，26-35岁略高(569元)\n4. **家居日用**在45岁以上有唯一销售记录(239元)，体现中老年群体的实际需求\n5. **零食饮料**整体销售额较低，主要来自年轻群体\n6. 整体趋势：年轻人偏好美妆、零食；中年人偏向电子产品和高价值商品；老年人关注家居用品', '1', '成功', 2043241068644618241, '2026-05-29 22:42:33', '2026-05-29 22:45:52', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060372729421217793, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"不同年龄段对各商品分类的销售金额分析\",\n    \"left\": \"center\",\n    \"textStyle\": {\n      \"fontSize\": 16,\n      \"fontWeight\": \"bold\"\n    }\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": function(params) {\n      let result = params[0].name + \'<br/>\';\n      params.forEach(function(item) {\n        if (item.value > 0) {\n          result += item.marker + item.seriesName + \': ¥\' + item.value + \'<br/>\';\n        }\n      });\n      return result;\n    }\n  },\n  \"legend\": {\n    \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"],\n    \"top\": 30,\n    \"type\": \"scroll\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"],\n    \"axisLabel\": {\n      \"fontSize\": 12\n    }\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"销售金额(元)\",\n    \"axisLabel\": {\n      \"formatter\": \"¥{value}\"\n    }\n  },\n  \"series\": [\n    {\n      \"name\": \"18-25岁\",\n      \"type\": \"line\",\n      \"data\": [399, 424, 125, 329, 89],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 2\n      },\n      \"itemStyle\": {\n        \"color\": \"#5470c6\"\n      }\n    },\n    {\n      \"name\": \"26-35岁\",\n      \"type\": \"line\",\n      \"data\": [799, 199, 159, 569, 68],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 2\n      },\n      \"itemStyle\": {\n        \"color\": \"#91cc75\"\n      }\n    },\n    {\n      \"name\": \"36-45岁\",\n      \"type\": \"line\",\n      \"data\": [1898, 0, 0, 459, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 2\n      },\n      \"itemStyle\": {\n        \"color\": \"#fac858\"\n      }\n    },\n    {\n      \"name\": \"45岁以上\",\n      \"type\": \"line\",\n      \"data\": [0, 0, 239, 0, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 2\n      },\n      \"itemStyle\": {\n        \"color\": \"#ee6666\"\n      }\n    }\n  ]\n}', '通过对不同年龄段与商品分类的销售金额交叉分析，得出以下结论：\n1. **36-45岁群体消费能力最强**：该年龄段在电子产品上消费高达1898元，远超其他年龄段，显示中年群体对高价值电子产品购买力突出。\n2. **18-25岁偏好美妆与服饰**：年轻群体在美妆护肤（424元）和服装鞋帽（329元）上投入较高，符合年轻人的消费特征。\n3. **26-35岁消费分布最均衡**：该年龄段在各品类均有消费，其中服装鞋帽（569元）和电子产品（799元）占比较高，是核心消费人群。\n4. **45岁以上样本较少**：仅有家居日用类消费（239元），数据代表性有限。\n5. **电子产品为最高销售额品类**：整体来看，电子产品是所有品类中总销售额最高的类别。', '1', '成功', 2043241068644618241, '2026-05-29 22:48:33', '2026-05-29 22:53:25', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060374382752940034, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"不同年龄段对各商品销售金额分析\",\n    \"left\": \"center\",\n    \"textStyle\": {\n      \"fontSize\": 18,\n      \"fontWeight\": \"bold\"\n    }\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": function(params) {\n      let result = params[0].axisValue + \'<br/>\';\n      params.forEach(function(item) {\n        if (item.value > 0) {\n          result += item.marker + item.seriesName + \': ¥\' + item.value + \'<br/>\';\n        }\n      });\n      return result;\n    }\n  },\n  \"legend\": {\n    \"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"],\n    \"top\": 40,\n    \"type\": \"scroll\"\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"4%\",\n    \"bottom\": \"3%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"],\n    \"boundaryGap\": false,\n    \"axisLabel\": {\n      \"fontSize\": 13\n    }\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"销售金额(元)\",\n    \"axisLabel\": {\n      \"formatter\": \"¥{value}\"\n    }\n  },\n  \"series\": [\n    {\n      \"name\": \"电子产品\",\n      \"type\": \"line\",\n      \"data\": [399, 799, 1898, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#5470c6\"}\n    },\n    {\n      \"name\": \"美妆护肤\",\n      \"type\": \"line\",\n      \"data\": [424, 199, 0, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#91cc75\"}\n    },\n    {\n      \"name\": \"家居日用\",\n      \"type\": \"line\",\n      \"data\": [125, 159, 0, 239],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#fac858\"}\n    },\n    {\n      \"name\": \"服装鞋帽\",\n      \"type\": \"line\",\n      \"data\": [329, 569, 459, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#ee6666\"}\n    },\n    {\n      \"name\": \"零食饮料\",\n      \"type\": \"line\",\n      \"data\": [89, 68, 0, 0],\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\"width\": 3},\n      \"itemStyle\": {\"color\": \"#73c0de\"}\n    }\n  ]\n}', '1. **数据分析结论**：\n   - **36-45岁群体**在电子产品上消费最高（1898元），是该品类的主力消费人群，显示出较强的购买力；\n   - **18-25岁年轻群体**消费偏好分散，美妆护肤（424元）和服装鞋帽（329元）为主要支出项；\n   - **26-35岁群体**覆盖品类最广，电子产品（799元）和服装鞋帽（569元）为核心消费；\n   - **45岁以上群体**样本量较小，仅在家居日用（239元）上有消费记录；\n   - 整体来看，电子产品在各年龄段中均占重要地位，尤其受中青年青睐。', '1', '成功', 2043241068644618241, '2026-05-29 22:55:07', '2026-05-29 23:02:18', 1);
INSERT INTO `chart` (`id`, `goal`, `name`, `chartData`, `chartType`, `genChart`, `genResult`, `status`, `execMessage`, `userId`, `createTime`, `updateTime`, `isDelete`) VALUES (2060376329140588546, '分析不同年龄段对不同商品的销售金额', '销售分析', '订单 ID,性别,年龄段,商品分类,购买数量,订单金额,下单日期\n1001,男,18-25,电子产品,1,399,2025/1/5\n1002,女,18-25,美妆护肤,2,268,2025/1/5\n1003,男,26-35,家居日用,3,159,2025/1/6\n1004,女,36-45,服装鞋帽,1,459,2025/1/6\n1005,男,26-35,电子产品,2,799,2025/1/7\n1006,女,18-25,零食饮料,5,89,2025/1/7\n1007,男,45 以上,家居日用,2,239,2025/1/8\n1008,女,26-35,美妆护肤,1,199,2025/1/8\n1009,男,18-25,服装鞋帽,2,329,2025/1/9\n1010,女,36-45,电子产品,1,1299,2025/1/9\n1011,男,26-35,零食饮料,4,68,2025/1/10\n1012,女,26-35,服装鞋帽,3,569,2025/1/10\n1013,男,36-45,电子产品,1,599,2025/1/11\n1014,女,18-25,家居日用,2,125,2025/1/11\n1015,男,18-25,美妆护肤,1,156,2025/1/12\n', '折线图', '{\n  \"title\": {\n    \"text\": \"不同年龄段对各商品分类的销售金额分析\",\n    \"left\": \"center\",\n    \"textStyle\": {\n      \"fontSize\": 18,\n      \"fontWeight\": \"bold\",\n      \"color\": \"#333\"\n    }\n  },\n  \"tooltip\": {\n    \"trigger\": \"axis\",\n    \"formatter\": \"\"\n  },\n  \"legend\": {\n    \"data\": [\"电子产品\", \"美妆护肤\", \"家居日用\", \"服装鞋帽\", \"零食饮料\"],\n    \"top\": \"8%\",\n    \"itemWidth\": 20,\n    \"itemHeight\": 12,\n    \"textStyle\": {\n      \"fontSize\": 12\n    }\n  },\n  \"grid\": {\n    \"left\": \"3%\",\n    \"right\": \"5%\",\n    \"bottom\": \"10%\",\n    \"top\": \"22%\",\n    \"containLabel\": true\n  },\n  \"xAxis\": {\n    \"type\": \"category\",\n    \"data\": [\"18-25岁\", \"26-35岁\", \"36-45岁\", \"45岁以上\"],\n    \"boundaryGap\": false,\n    \"axisLine\": {\n      \"lineStyle\": {\n        \"color\": \"#666\"\n      }\n    },\n    \"axisLabel\": {\n      \"fontSize\": 13,\n      \"color\": \"#333\"\n    }\n  },\n  \"yAxis\": {\n    \"type\": \"value\",\n    \"name\": \"销售金额(元)\",\n    \"nameTextStyle\": {\n      \"fontSize\": 13,\n      \"color\": \"#666\"\n    },\n    \"axisLine\": {\n      \"show\": true,\n      \"lineStyle\": {\n        \"color\": \"#666\"\n      }\n    },\n    \"splitLine\": {\n      \"lineStyle\": {\n        \"type\": \"dashed\",\n        \"color\": \"#e0e0e0\"\n      }\n    },\n    \"axisLabel\": {\n      \"fontSize\": 12,\n      \"color\": \"#666\"\n    }\n  },\n  \"series\": [\n    {\n      \"name\": \"电子产品\",\n      \"type\": \"line\",\n      \"data\": [399, 799, 1898, 0],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#5470C6\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#5470C6\"\n      },\n      \"label\": {\n        \"show\": true,\n        \"position\": \"top\",\n        \"fontSize\": 11,\n        \"color\": \"#5470C6\",\n        \"formatter\": \"\"\n      }\n    },\n    {\n      \"name\": \"美妆护肤\",\n      \"type\": \"line\",\n      \"data\": [424, 199, 0, 0],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#91CC75\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#91CC75\"\n      },\n      \"label\": {\n        \"show\": true,\n        \"position\": \"top\",\n        \"fontSize\": 11,\n        \"color\": \"#91CC75\",\n        \"formatter\": \"\"\n      }\n    },\n    {\n      \"name\": \"家居日用\",\n      \"type\": \"line\",\n      \"data\": [125, 159, 0, 239],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#FAC858\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#FAC858\"\n      },\n      \"label\": {\n        \"show\": true,\n        \"position\": \"top\",\n        \"fontSize\": 11,\n        \"color\": \"#FAC858\",\n        \"formatter\": \"\"\n      }\n    },\n    {\n      \"name\": \"服装鞋帽\",\n      \"type\": \"line\",\n      \"data\": [329, 569, 459, 0],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#EE6666\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#EE6666\"\n      },\n      \"label\": {\n        \"show\": true,\n        \"position\": \"top\",\n        \"fontSize\": 11,\n        \"color\": \"#EE6666\",\n        \"formatter\": \"\"\n      }\n    },\n    {\n      \"name\": \"零食饮料\",\n      \"type\": \"line\",\n      \"data\": [89, 68, 0, 0],\n      \"smooth\": true,\n      \"symbol\": \"circle\",\n      \"symbolSize\": 8,\n      \"lineStyle\": {\n        \"width\": 3,\n        \"color\": \"#73C0DE\"\n      },\n      \"itemStyle\": {\n        \"color\": \"#73C0DE\"\n      },\n      \"label\": {\n        \"show\": true,\n        \"position\": \"top\",\n        \"fontSize\": 11,\n        \"color\": \"#73C0DE\",\n        \"formatter\": \"\"\n      }\n    }\n  ]\n}', '从数据分析来看，36-45岁年龄段在电子产品上的消费金额最高（1898元），远超其他年龄段；26-35岁是消费最均衡的群体，覆盖了所有5个商品类别，其中电子产品（799元）和服装鞋帽（569元）是其主要消费品类；18-25岁群体偏好美妆护肤（424元）、服装鞋帽（329元）和电子产品（399元）；45岁以上群体仅在家居日用类有消费记录（239元）。总体而言，电子产品是销售额最高的品类，且主要消费力集中在26-45岁的中青年群体。', '1', '成功', 2043241068644618241, '2026-05-29 23:02:51', '2026-05-29 23:03:13', 0);
